"use client";

type TopicNode = {
  id: string;
  title: string;
  category: "parent" | "child" | "leaf";
};

type TopicArchitectureProps = {
  topics: TopicNode[];
  title: string;
  description: string;
};

export function TopicArchitecture({
  topics,
  title,
  description,
}: TopicArchitectureProps) {
  // Organize topics by hierarchy
  const parentTopics = topics.filter((t) => t.category === "parent");
  const childTopics = topics.filter((t) => t.category === "child");

  return (
    <div className="space-y-8">
      <div>
        <h3 className="font-[var(--font-heading)] text-2xl font-semibold text-[#111111] md:text-3xl">
          {title}
        </h3>
        <p className="mt-3 text-sm leading-relaxed text-[#5f5f5a]">{description}</p>
      </div>

      {/* Visual taxonomy */}
      <div className="rounded-2xl border border-[#e1ddd5] bg-[#f8f8f6] p-8 md:p-12">
        <div className="space-y-12">
          {parentTopics.map((parent, parentIdx) => (
            <div key={parent.id}>
              {/* Parent node */}
              <div className="mb-6 inline-block rounded-xl border-2 border-[#ff5a1f] bg-white px-6 py-3">
                <span className="font-[var(--font-heading)] font-semibold text-[#111111]">
                  {parent.title}
                </span>
              </div>

              {/* Child nodes */}
              <div className="ml-4 grid gap-3 md:grid-cols-3">
                {childTopics
                  .filter((_, idx) => {
                    const childrenPerParent = Math.ceil(
                      childTopics.length / parentTopics.length
                    );
                    return (
                      idx >= parentIdx * childrenPerParent &&
                      idx < (parentIdx + 1) * childrenPerParent
                    );
                  })
                  .map((child) => (
                    <div
                      key={child.id}
                      className="rounded-lg border border-[#d9d6cf] bg-white px-4 py-3"
                    >
                      <p className="text-sm font-medium text-[#111111]">
                        {child.title}
                      </p>
                    </div>
                  ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Key insight */}
      <div className="rounded-2xl border border-[#d9d6cf] bg-white p-8">
        <p className="text-sm leading-relaxed text-[#5f5f5a]">
          <strong className="text-[#111111]">Søkearkitektur:</strong> Hver tema er
          optimalisert som separate søkeenheter — både for tradisjonell søk og
          AI-genererte svar. Interne lenker kobler temaene inn i en sammenhengende
          visibilitetskjede.
        </p>
      </div>
    </div>
  );
}
