"use client";

import { useEffect, useMemo, useState } from "react";

type InsightTab = {
  id: string;
  title: string;
  highlights: string[];
  microcopy?: string;
};

type PreviewMode = "image" | "before-after";

type CaseCardProps = {
  id: string;
  image: string;
  imageAlt: string;
  imageLabel?: string;
  previewMode?: PreviewMode;
  showHeader?: boolean;
  title: string;
  summary: string;
  result: string;
  resultLabel: string;
  category: string;
  tags: string[];
  insightTabs?: InsightTab[];
  ctaLabel?: string;
  ctaHref?: string;
  href?: string;
};

export function AnswerBlock({ question, answer }: { question: string; answer: string }) {
  return (
    <div className="rounded-lg border border-[#dfdbd2] bg-white px-3 py-2.5">
      <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#5f5f5a]">{question}</p>
      <p className="mt-1.5 text-xs leading-relaxed text-[#111111]">{answer}</p>
    </div>
  );
}

export function FAQPreview({ items }: { items: string[] }) {
  return (
    <div className="space-y-2 rounded-lg border border-[#dfdbd2] bg-white p-3">
      <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#5f5f5a]">FAQ</p>
      {items.slice(0, 3).map((item) => (
        <div
          key={item}
          className="flex items-center justify-between rounded-md border border-[#ebe7de] bg-[#f8f8f6] px-2.5 py-2 text-xs text-[#111111]"
        >
          <span>{item}</span>
          <span className="text-[#7b7771]">+</span>
        </div>
      ))}
    </div>
  );
}

export function BeforeAfterModule() {
  return (
    <div className="grid h-full grid-cols-2 gap-2 bg-[#efece5] p-2">
      <div className="rounded-lg border border-[#d8d3c8] bg-[#ece7dc] p-3">
        <p className="text-[10px] font-semibold uppercase tracking-[0.1em] text-[#7b7771]">Before</p>
        <div className="mt-2.5 space-y-2 text-[11px] text-[#6a6661]">
          <div className="h-2.5 w-full rounded bg-[#d9d3c8]" />
          <div className="h-2.5 w-[84%] rounded bg-[#d9d3c8]" />
          <div className="h-2.5 w-[92%] rounded bg-[#d9d3c8]" />
          <div className="h-2.5 w-[70%] rounded bg-[#d9d3c8]" />
        </div>
        <p className="mt-3 text-[11px] leading-relaxed text-[#7b7771]">
          Lange tekstblokker, svake informasjonsnoder, lav scanability.
        </p>
      </div>

      <div className="space-y-2 rounded-lg border border-[#d8d3c8] bg-[#f5f3ee] p-3">
        <p className="text-[10px] font-semibold uppercase tracking-[0.1em] text-[#5f5f5a]">After</p>
        <AnswerBlock question="Hvordan henge opp gardiner?" answer="Stegvis guide med måling, skinnevalg og neste steg." />
        <FAQPreview
          items={[
            "Hvilke gardiner passer til takskinne?",
            "Hvor bred bør skinnen være?",
            "Hvordan måle gardinlengde?",
          ]}
        />
      </div>
    </div>
  );
}

export function InsightTabs({
  tabs,
  activeTabId,
  onChange,
}: {
  tabs: InsightTab[];
  activeTabId: string;
  onChange: (tabId: string) => void;
}) {
  return (
    <div className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
      {tabs.map((tab) => {
        const isActive = tab.id === activeTabId;
        return (
          <button
            key={tab.id}
            type="button"
            onClick={() => onChange(tab.id)}
            className={[
              "shrink-0 rounded-full border px-3 py-1.5 text-[11px] font-semibold uppercase tracking-[0.08em] transition-colors duration-200",
              isActive
                ? "border-[#111111] bg-[#111111] text-white"
                : "border-[#d9d6cf] bg-[#f8f8f6] text-[#5f5f5a] hover:border-[#111111] hover:text-[#111111]",
            ].join(" ")}
          >
            {tab.title}
          </button>
        );
      })}
    </div>
  );
}

export function TabPanel({ tab }: { tab: InsightTab }) {
  return (
    <div className="space-y-5 opacity-100 transition-opacity duration-200">
      <h4 className="text-xs font-semibold uppercase tracking-[0.12em] text-[#5f5f5a]">{tab.title}</h4>
      <ul className="space-y-2.5">
        {tab.highlights.slice(0, 5).map((item) => (
          <li key={item} className="flex items-start gap-2 text-sm leading-normal text-[#111111]">
            <span className="mt-[0.45rem] h-1.5 w-1.5 shrink-0 rounded-full bg-[#ff5a1f]" />
            {item}
          </li>
        ))}
      </ul>
      {tab.microcopy && (
        <p className="text-xs italic leading-relaxed text-[#7b7771]">{tab.microcopy}</p>
      )}
    </div>
  );
}

export function ResultHighlight({
  result,
  resultLabel,
  ctaLabel,
  ctaHref,
}: {
  result: string;
  resultLabel: string;
  ctaLabel?: string;
  ctaHref?: string;
}) {
  return (
    <div className="flex items-end justify-between gap-5 border-t border-[#e8e5e0] pt-5">
      <div>
        <div className="font-[var(--font-heading)] text-3xl font-bold leading-none tracking-tight text-[#111111]">
          {result}
        </div>
        <div className="mt-1 max-w-[34ch] text-xs leading-relaxed text-[#5f5f5a]">{resultLabel}</div>
      </div>
      {ctaLabel && ctaHref && (
        <div className="hidden h-9 w-px bg-[#e8e5e0] md:block" aria-hidden="true" />
      )}
      {ctaLabel && ctaHref && (
        <a
          href={ctaHref}
          className="inline-flex shrink-0 items-center gap-1 text-sm font-semibold text-[#111111] transition-colors duration-200 hover:text-[#ff5a1f]"
        >
          {ctaLabel}
          <span aria-hidden="true">→</span>
        </a>
      )}
    </div>
  );
}

export function CaseStudyCard({
  id: _id,
  image,
  imageAlt,
  imageLabel,
  previewMode = "image",
  showHeader = false,
  title,
  summary,
  result,
  resultLabel,
  category,
  tags,
  insightTabs = [],
  ctaLabel = "Se case",
  ctaHref = "#form",
}: CaseCardProps) {
  const [isHovered, setIsHovered] = useState(false);
  const [activeTabId, setActiveTabId] = useState(insightTabs[0]?.id || "");

  useEffect(() => {
    setActiveTabId(insightTabs[0]?.id || "");
  }, [insightTabs]);

  const activeTab = useMemo(
    () => insightTabs.find((tab) => tab.id === activeTabId) || insightTabs[0],
    [activeTabId, insightTabs],
  );

  return (
    <article
      className="group flex h-full flex-col overflow-hidden rounded-2xl border border-[#d9d6cf] bg-white transition-all duration-300 hover:shadow-[0_32px_80px_-24px_rgba(17,17,17,0.12)]"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Visual preview */}
      <div className="relative aspect-[16/9] overflow-hidden bg-[#f3f3f1]">
        {previewMode === "before-after" ? (
          <BeforeAfterModule />
        ) : (
          <img
            src={image}
            alt={imageAlt}
            className={`h-full w-full object-cover object-top transition-transform duration-500 ${
              isHovered ? "scale-[1.02]" : "scale-100"
            }`}
            loading="lazy"
          />
        )}
        {imageLabel && (
          <div className="absolute left-4 top-4 rounded-full border border-[#d9d6cf] bg-white/95 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.12em] text-[#5f5f5a] backdrop-blur">
            {imageLabel}
          </div>
        )}
      </div>

      {/* Insight area */}
      <div className="flex flex-1 flex-col gap-6 p-6 md:p-7">
        {showHeader && (
          <div className="space-y-4 border-b border-[#ece9e3] pb-5">
            <div className="flex flex-wrap items-center gap-2">
              <span className="inline-block rounded-full border border-[#e1ddd5] bg-[#f8f8f6] px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.1em] text-[#5f5f5a]">
                {category}
              </span>
              {tags.slice(0, 4).map((tag) => (
                <span
                  key={`${_id}-${tag}`}
                  className="inline-block rounded-full border border-[#e1ddd5] bg-transparent px-2.5 py-0.5 text-[10px] font-medium uppercase tracking-[0.08em] text-[#5f5f5a]"
                >
                  {tag}
                </span>
              ))}
            </div>
            <h3 className="max-w-[26ch] font-[var(--font-heading)] text-2xl font-semibold leading-tight text-[#111111] md:text-[2rem]">
              {title}
            </h3>
            <p className="max-w-[58ch] text-sm leading-relaxed text-[#5f5f5a]">{summary}</p>
          </div>
        )}

        {insightTabs.length > 0 && (
          <div className="space-y-4">
            <InsightTabs tabs={insightTabs} activeTabId={activeTab?.id || ""} onChange={setActiveTabId} />
            {activeTab && <TabPanel key={activeTab.id} tab={activeTab} />}
          </div>
        )}

        <ResultHighlight result={result} resultLabel={resultLabel} ctaLabel={ctaLabel} ctaHref={ctaHref} />
      </div>
    </article>
  );
}
