"use client";

import { ReactNode } from "react";

type CaseStudyTemplateProps = {
  // Hero
  heroImage: string;
  heroImageAlt: string;
  heroTitle: string;
  heroSummary: string;
  categories: string[];
  tags: string[];
  resultMetric: string;
  resultLabel: string;

  // Sections
  children: ReactNode;

  // Footer CTA
  ctaLabel?: string;
  ctaHref?: string;
};

export function CaseStudyTemplate({
  heroImage,
  heroImageAlt,
  heroTitle,
  heroSummary,
  categories,
  tags,
  resultMetric,
  resultLabel,
  children,
  ctaLabel = "Snakk med oss",
  ctaHref = "#form",
}: CaseStudyTemplateProps) {
  return (
    <main className="bg-[#f8f8f6] text-[#111111] font-[var(--font-body)]">
      {/* HERO */}
      <section className="relative">
        {/* Hero image */}
        <div className="aspect-video overflow-hidden bg-[#e1ddd5] md:aspect-auto md:h-[600px]">
          <img
            src={heroImage}
            alt={heroImageAlt}
            className="h-full w-full object-cover"
            loading="lazy"
          />
        </div>

        {/* Hero overlay content */}
        <div className="relative mx-auto max-w-[1280px] px-6 py-16 md:px-10 md:py-24">
          <div className="space-y-8">
            {/* Category & Tags */}
            <div className="flex flex-wrap items-center gap-2">
              {categories.map((cat) => (
                <span
                  key={cat}
                  className="inline-block rounded-full border border-[#d9d6cf] bg-white px-3 py-1 text-xs font-semibold uppercase tracking-[0.1em] text-[#5f5f5a] shadow-sm"
                >
                  {cat}
                </span>
              ))}
              {tags.map((tag) => (
                <span
                  key={tag}
                  className="inline-block rounded-full border border-[#d9d6cf] bg-transparent px-2.5 py-0.5 text-[10px] font-medium uppercase tracking-[0.08em] text-[#5f5f5a]"
                >
                  {tag}
                </span>
              ))}
            </div>

            {/* Title */}
            <h1 className="font-[var(--font-heading)] text-4xl font-bold leading-tight tracking-tight text-[#111111] md:text-5xl lg:text-6xl">
              {heroTitle}
            </h1>

            {/* Summary */}
            <p className="max-w-2xl text-base leading-relaxed text-[#5f5f5a] md:text-lg">
              {heroSummary}
            </p>

            {/* Result highlight */}
            <div className="pt-4">
              <div className="inline-block rounded-2xl border border-[#d9d6cf] bg-white px-8 py-6 shadow-sm">
                <div className="font-[var(--font-heading)] text-4xl font-bold text-[#ff5a1f]">
                  {resultMetric}
                </div>
                <div className="mt-2 text-sm font-medium text-[#5f5f5a]">
                  {resultLabel}
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* CONTENT SECTIONS */}
      <div className="space-y-20 md:space-y-28">{children}</div>

      {/* FINAL CTA */}
      <section className="border-t border-[#d9d6cf] bg-[#111111]">
        <div className="mx-auto max-w-[1280px] px-6 py-24 md:px-10 md:py-32">
          <div className="flex flex-col items-start gap-8 md:flex-row md:items-end md:justify-between">
            <div>
              <h2 className="font-[var(--font-heading)] text-4xl font-bold leading-tight text-white md:text-5xl">
                Interessert i tilsvarende strategier?
              </h2>
              <p className="mt-4 max-w-xl text-base leading-relaxed text-[#9a9691]">
                Vi bygger søkestrategier basert på faktiske innsikter, ikke
                antagelser.
              </p>
            </div>
            <a
              href={ctaHref}
              className="shrink-0 inline-flex h-14 items-center rounded-full bg-[#ff5a1f] px-8 text-sm font-semibold text-white transition-all duration-200 hover:bg-[#e84f17]"
            >
              {ctaLabel}
            </a>
          </div>
        </div>
      </section>
    </main>
  );
}

export function CaseStudySection({
  title,
  children,
  subtitle,
  layout = "default",
}: {
  title: string;
  children: ReactNode;
  subtitle?: string;
  layout?: "default" | "split";
}) {
  return (
    <section className="border-t border-[#d9d6cf] bg-white">
      <div className="mx-auto max-w-[1280px] px-6 py-20 md:px-10 md:py-28">
        <div className="space-y-12">
          <div>
            <h2 className="font-[var(--font-heading)] text-3xl font-semibold leading-tight tracking-tight text-[#111111] md:text-4xl">
              {title}
            </h2>
            {subtitle && (
              <p className="mt-4 max-w-2xl text-base leading-relaxed text-[#5f5f5a]">
                {subtitle}
              </p>
            )}
          </div>
          {children}
        </div>
      </div>
    </section>
  );
}

export function CaseSectionSplit({
  title,
  text,
  children,
}: {
  title: string;
  text: string | ReactNode;
  children: ReactNode;
}) {
  return (
    <section className="border-t border-[#d9d6cf] bg-white">
      <div className="mx-auto max-w-[1280px] px-6 py-20 md:px-10 md:py-28">
        <div className="grid gap-12 md:grid-cols-[1fr_1.2fr] md:items-start">
          <div>
            <h2 className="font-[var(--font-heading)] text-3xl font-semibold leading-tight tracking-tight text-[#111111] md:text-4xl">
              {title}
            </h2>
            <div className="mt-6 space-y-4 text-sm leading-relaxed text-[#5f5f5a]">
              {typeof text === "string" ? <p>{text}</p> : text}
            </div>
          </div>
          <div className="space-y-6">{children}</div>
        </div>
      </div>
    </section>
  );
}
